package com.bank.birthday;

import java.time.*;
import java.util.*;
import java.util.logging.*;

public class BirthdayDemo {
    private static final Logger log = Logger.getLogger("Birthday");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        Clock clock = Clock.fixed(Instant.parse("2025-06-15T00:00:00Z"), ZoneOffset.UTC); // June
        List<Employee> staff = List.of(
            new Employee("Rajesh", LocalDate.parse("1990-06-20")),  // June ✓
            new Employee("Priya", LocalDate.parse("1988-03-01")),   // March ✗
            new Employee("Amit", LocalDate.parse("1995-06-05")));   // June ✓
        BirthdayService service = new BirthdayService(clock);

        List<String> celebrants = service.birthdaysThisMonth(staff);
        log.info(() -> "Birthdays this month: " + celebrants);
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final LocalDate dob;
    Employee(String name, LocalDate dob) { this.name = name; this.dob = dob; }
    String getName() { return name; }
    LocalDate getDob() { return dob; }
}

// ─── Would be in service/BirthdayService.java ───
class BirthdayService {
    private final Clock clock;
    BirthdayService(Clock clock) { this.clock = clock; }

    List<String> birthdaysThisMonth(List<Employee> staff) {
        Month currentMonth = LocalDate.now(clock).getMonth();   // injectable now
        return staff.stream()
            .filter(e -> e.getDob() != null)                    // guard null dob
            .filter(e -> e.getDob().getMonth() == currentMonth) // match month only
            .map(Employee::getName)
            .toList();
    }
}
